async function load(){const r=await fetch('/data/products.json');return (await r.json()).products}function draw(ps){document.querySelector('#filter-grid').innerHTML=ps.map(p=>`<article class="product-card" data-product-id="${p.id}" data-category="${p.category}"><img src="${p.image}" alt="${p.name}"><h2>${p.name}</h2><p class="price">$${p.price}</p></article>`).join('')}load().then(all=>{let current='all';const status=document.querySelector('#filter-status');function apply(f){current=f;document.querySelectorAll('.filter').forEach(b=>b.classList.toggle('is-selected',b.dataset.filter===f));if(f==='clear'||f==='all'){draw(all);status.textContent='Showing all products';return}const shown=all.filter(p=>p.category===f);draw(shown);status.textContent=shown.length?`Showing ${shown.length} ${f} product${shown.length===1?'':'s'}`:'No products match this filter'}document.querySelectorAll('.filter').forEach(b=>b.addEventListener('click',()=>apply(b.dataset.filter)));apply(current)});
